const iso = (t: string) => '\u2066' + t + '\u2069';
const PER: any = { CLHO: { lab: '6 شهور', until: '30 يونيو 2026', fac: 1, mult: 'ستة شهور' }, EGAL: { lab: 'سنة مالية 2025/26', until: '30 يونيو 2026', fac: 1, mult: 'سنة كاملة', ttl: 'سنة مالية 2025/26' } };
const per = (k?: string) => PER[k || ''] || { lab: '9 شهور', until: '30 سبتمبر 2026', fac: 4 / 3 };
const f = (v: number) => iso(v >= 1 ? v.toFixed(2) : v.toFixed(3));
const p1 = (v: number) => iso((v > 0 ? '+' : '') + v.toFixed(1) + '%');
import { PVN, NEW, pageOf, loadPilotM, usePage } from './page';
import { FinTabBlock } from './finblock';
const n1 = (n: number) => iso(n.toLocaleString('en-GB', { maximumFractionDigits: PVN() && Math.abs(n) < 1 ? 2 : 1 }));
const pvVol = (s: any, v: any) => { const b = (s.bars || []); const lv = b.length ? b[b.length - 1][5] : null; const lead = lv != null && Number.isFinite(lv) ? 'آخر جلسة اتداول فيها ' + Math.round(lv).toLocaleString('en-US') + ' سهم، يعني ' + s.volx + ' مرة قد المتوسط في آخر 20 جلسة. ده مقارنة بنفس السهم. الحجم من مصدر واحد، وبيعكس البيانات وقت اللقطة، وآخر شمعة ممكن تكون قبل المزاد الأخير.' : 'آخر جلسة اتداولت بحوالي ' + s.volx + ' مرة قد المتوسط في آخر 20 جلسة. ده مقارنة بنفس السهم. الحجم من مصدر واحد، وبيعكس البيانات وقت اللقطة، وآخر شمعة ممكن تكون قبل المزاد الأخير.'; return lead + (s.plan && s.plan.tv != null ? ' السيولة المعتادة (الرقم الأوسط لقيمة التداول اليومي في آخر 60 جلسة) حوالي ' + s.plan.tv + ' مليون جنيه في اليوم، وده حاجة تانية.' : ''); };
const MT_ATT = 'مجمل الربح 1,815.7 مليون مقابل 1,759.4، زاد 3% بس، والإيراد زاد 15.6%. يعني التكلفة المباشرة زادت أسرع من المبيعات، فمن كل جنيه مبيعات فضل ربح أقل من السنة اللي فاتت قبل المصاريف العامة. الربع التالت: المجمل زاد 11% (657.1 مليون مقابل 592.1) والإيراد زاد 17%، فالهامش 9.9% (أحسن من متوسط الـ9 شهور 9.4% لكن أقل من 10.4% في نفس الربع السنة اللي فاتت). ';
const MT_LIM = 'فحص محدود من غير تحفظات: المراجع فحص القوائم فحص أخف من التدقيق الكامل، ومكتبش إنه مش موافق على أي بند.';
const pvDec = (k: string) => { const d = DEC[k]; const pg = pageOf(k); return PVN() && NEW(k) && pg && pg.dec_ar ? { ...(d || {}), up: pg.dec_ar.up, down: pg.dec_ar.down, flip: pg.dec_ar.flip } : d; };

