function techItems(s: any): Item[] {
  const v = s.votes || {}, p = s.plan || {}, o: Item[] = [];
  o.push({
    label: 'الاتجاه الطويل (متوسط 200 جلسة)', value: v.trend ? 'فوقه' : 'تحته', tone: v.trend ? 'ok' : 'no',
    mean: PVN() ? 'خد سعر إقفال السهم في آخر 200 يوم تداول (حوالي 9.5 شهر) واعمل منهم متوسط. ده بيقولك "السعر المعتاد للسهم" في الفترة دي. لو السعر النهارده فوقه، يبقى السهم أعلى من معتاده في الفترة دي.' : 'خد سعر إقفال السهم في آخر 200 يوم تداول (حوالي 9 شهور) واعمل منهم متوسط. ده بيقولك "السعر المعتاد للسهم" في الفترة دي. لو السعر النهارده فوقه، يبقى السهم أعلى من معتاده، ومعظم اللي اشتروا في الفترة دي تقريبًا رابحين.',
    effect: (() => { const cl = (s.bars || []).map((b: any) => b[4]); const m200 = cl.length >= 200 ? cl.slice(-200).reduce((x: number, y: number) => x + y, 0) / 200 : null; const above = m200 != null ? cl[cl.length - 1] > m200 : !!v.trend; return PVN() ? (above ? 'السعر أعلى من متوسط آخر 200 جلسة (حوالي 9.5 شهر). لو نزل تحته، الصورة بتضعف. ده وصف للي حصل مش توقع.' : 'السعر أقل من متوسط آخر 200 جلسة (حوالي 9.5 شهر). لو قفل فوقه، الصورة بتتحسن. ده وصف للي حصل مش توقع.') : (above ? 'السعر أعلى من متوسط آخر 200 يوم (حوالي 10 شهور). لو نزل تحته، الصورة بتضعف. ده وصف للي حصل مش توقع.' : 'السعر أقل من متوسط آخر 200 يوم (حوالي 10 شهور). لو قفل فوقه، الصورة بتتحسن. ده وصف للي حصل مش توقع.'); })(),
  });
  o.push({
    label: 'الاتجاه المتوسط (متوسط 50 جلسة)', value: v.mid ? 'فوقه' : 'تحته', tone: v.mid ? 'ok' : 'no',
    mean: 'نفس فكرة متوسط 200 بس لآخر 50 يوم تداول (حوالي شهرين ونص). بيوريك السهم ماشي إزاي في الفترة القريبة، من غير ما الشهور القديمة تأثر.',
    effect: v.mid ? 'الفترة القريبة كويسة: السعر أعلى من معتاده الأخير.' : 'الفترة القريبة ضعيفة: السعر أقل من معتاده الأخير. السهم محتاج يقفل فوقه عشان يبان تحسن.'
  });
  const rsi = s.rsi;
  o.push({
    label: 'قوة الحركة (RSI)', value: String(rsi), tone: rsi > 70 || rsi < 30 ? 'mid' : 'ok',
    mean: 'رقم من 0 لـ100 بيقيس سرعة حركة السعر في آخر 14 جلسة. تخيله عداد حرارة: فوق 70 يعني السعر صعد بسرعة كبيرة (سخن)، وتحت 30 يعني نزل بسرعة كبيرة (برد). بين 30 و70 يبقى عادي.',
    effect: rsi > 70 ? 'السعر صعد بسرعة، وممكن يهدى أو يرجع شوية. بس مش لازم، وسهم ممكن يفضل سخن فترة.' : rsi < 30 ? 'السعر نزل بسرعة، وممكن يهدى. بس مش ضمان إنه يرتد.' : 'الرقم بين 30 و70، مش في منطقة تشبع بيع أو شراء، ومش بيدي إشارة لوحده.'
  });
  o.push({
    label: 'اتجاه السرعة (MACD)', value: v.macd ? 'أعلى من خطه' : 'أقل من خطه', tone: v.macd ? 'ok' : 'no',
    mean: 'تخيل عربية. السعر هو مكانها، والـMACD هو عداد سرعتها: هل بتسرّع ولا بتبطّأ. بيقارن حركة السعر في الأيام الأخيرة بحركته في الأسابيع الأخيرة، وبيرسم "خط إشارة" عشان تعرف اتجاه السرعة.',
    effect: v.macd ? 'الـMACD فوق خطه: السعر بيتحرك لفوق أسرع من المعتاد مؤخرًا. ده بيقيس السرعة مش المكان.' : 'الـMACD تحت خطه: الحركة لفوق بتتباطأ أو النزول بيزيد. ده بيقيس السرعة مش المكان، فممكن سهم يكون نازل بس بيبطّأ النزول، وأي ارتداد محتاج يتأكد.'
  });
  o.push({
    label: 'حجم التداول', value: s.volx + '×', tone: v.vol ? 'ok' : 'mid',
    mean: PVN() ? 'عدد الأسهم اللي اتباعت واتشرت في آخر جلسة، مقارنة بمتوسط آخر 20 جلسة. 1× يعني زي المتوسط، و2× يعني ضعف المتوسط. الحجم زي صوت السوق: كل ما زاد، اهتمام الناس بالحركة أكبر.' : 'عدد الأسهم اللي اتباعت واتشرت في آخر جلسة، مقارنة بمتوسط 20 جلسة قبلها. 1× يعني زي المعتاد، و2× يعني ضعف المعتاد. الحجم زي صوت السوق: كل ما زاد، اهتمام الناس بالحركة أكبر.',
    effect: PVN() ? pvVol(s, v) : s.volx < 0.7 ? 'التداول أقل من المعتاد (أقل من 0.7×)، يعني قليلين بس هم اللي بيتحركوا، فحركة السعر دي ضعيفة الدلالة.' : s.volx >= 1.5 ? 'نشاط أعلى من المعتاد (1.5× أو أكتر). لو مع صعود فده أقوى، بس الحجم لوحده مش بيقولك مين اللي بيشتري.' : 'قريب من المعتاد (بين 0.7× و1.5×)، فمفيش تأكيد خاص من الحجم.'
  });
  o.push({
    label: 'الهزة اليومية (ATR)', value: p.atrpct + '%', tone: 'mid',
    mean: PVN() ? 'كام في المية السهم بيتحرك في اليوم العادي: متوسط ممهَّد لمدى الحركة اليومي شامل الفجوات بين الإقفال والفتح، لآخر 14 جلسة. بتقيس التحرك مش الاتجاه.' : 'متوسط المسافة اللي السهم بيتحركها في اليوم الواحد من أعلى سعر لأقل سعر، بالنسبة المئوية من سعر الإقفال، متوسط المدى الحقيقي لآخر 14 جلسة بطريقة ويلدر (ممهَّد)، ويشمل الفجوات بين الإقفال والفتح. زي "المشوار اليومي" للسهم. بيقيس الهزة مش الاتجاه.',
    effect: p.atrpct >= 4 ? 'السهم بيهتز كتير في اليوم، يعني ممكن يتحرك 4% أو أكتر في يوم عادي. فأي مستوى قريب من السعر بيتكسر بسهولة.' : 'هزة يومية معتدلة، يعني حركة اليوم العادية مش كبيرة.'
  });
  if (p.res && p.sup) {
    const dr = (p.res / s.close - 1) * 100, ds = (p.sup / s.close - 1) * 100;
    o.push({
      label: 'مقاومة ودعم (20 جلسة)', value: f(p.res) + ' / ' + f(p.sup), tone: 'mid',
      mean: 'أعلى سعر خلال اليوم (High) وأقل سعر خلال اليوم (Low) وصلهم السهم في آخر 20 جلسة (مش الإقفال). أعلى سعر (المقاومة) زي سقف الأوضة اللي السعر قرب منه ورجع، وأقل سعر (الدعم) زي الأرضية اللي نزل عليها ولقى حد بيشتري. مش حدود مضمونة، السعر ممكن يكسرهم.',
      effect: 'المقاومة بتبعد ' + p1(dr) + ' عن السعر، والدعم ' + p1(ds) + '. لو السعر عدّى السقف مع تداول كبير بيبقى ده علامة قوة، ولو كسر الأرضية بيبقى علامة ضعف. ده وصف مش أمر.'
    });
  }
  o.push({
    label: 'التغير', value: 'آخر 20 جلسة: ' + p1(s.chg20) + ' · آخر 60 جلسة: ' + p1(s.chg60), tone: s.chg60 >= 0 ? 'ok' : 'no',
    mean: 'كام في المية اتغير سعر الإقفال في آخر شهر وآخر 3 شهور.',
    effect: 'ده وصف للي حصل، مش للي جاي. مثلًا لو الـ3 شهور سلبية والشهر الأخير أحسن، ممكن تكون بداية تعافي، بس لسه محتاجة تتأكد.'
  });
  return o;
}

function techSummary(s: any): string {
  const v = s.votes || {}, p = s.plan || {};
  let a = 'وضع السعر: ' + (v.trend ? 'فوق' : 'تحت') + ' متوسط 200 جلسة و' + (v.mid ? 'فوق' : 'تحت') + ' متوسط 50 جلسة';
  a += v.macd ? '، وMACD فوق خطه.' : '، وMACD تحت خطه.';
  if (s.rsi > 70) a += ' السعر صعد بسرعة.'; else if (s.rsi < 30) a += ' السعر نزل بسرعة.';
  if (p.res) { const dr = (p.res / s.close - 1) * 100; a += dr > 0.5 ? ' أعلى سعر لحظي في آخر 20 جلسة أعلى من السعر بـ ' + iso(dr.toFixed(1) + '%') + '.' : ' السعر قريب من أعلى مستوى في 20 جلسة.'; }
  return a;
}

const nm = (r: any) => (r.margin != null && r.revenue > 0 && r.profit != null) ? Math.round(r.profit / r.revenue * 1000) / 10 : r.margin;
function finSummary(k: string, r: any): string {
  if (k === 'BONY') return 'إيجار الشركة زاد 19% والربح المتكرر (حسب تعريف الشركة) زاد 129%، بس أغلب الربح المعلن إعادة تقييم عقارات مش كاش.';
  if (!r) return '';
  const g = r.prior ? (r.revenue / r.prior - 1) * 100 : null;
  if (r.norev) return 'ربح مساهمي الأم ' + n1(r.profit) + (k === 'VLMRA' ? ' م دولار' : ' م') + ' في ' + per(k).lab + '. القوائم مش بتعرض بند إيراد واحد، فالأرقام التفصيلية تحت.';
  if (g != null) return 'إيراد ' + per(k).lab + ' ' + (g >= 0 ? 'زاد ' : 'نزل ') + iso(Math.abs(g).toFixed(1) + '%') + ' عن نفس الفترة السنة اللي فاتت، وربح مساهمي الأم حوالي ' + iso(nm(r) + '%') + ' من الإيراد.';
  return 'الشركة حققت إيراد ' + n1(r.revenue) + (k === 'VLMRA' ? ' م دولار' : ' م') + ' وربح مساهمي الأم' + (k === 'MASR' ? ' قبل نصيب العاملين والمجلس (بعده 1,588.0 م)' : '') + ' ' + n1(r.profit) + (k === 'VLMRA' ? ' م دولار' : ' م') + ' في ' + per(k).lab + '، يعني حوالي ' + iso(nm(r) + '%') + ' من الإيراد.';
}

