function fairCard(s: any, k: string, r: any) {
  if (k === 'BONY') {
    const lo = 6.51, mid = 7.20, hi = 7.89;
    return <div className="gd-fv"><h4>السعر العادل: تقدير دفتري مؤرخ، تقدير تجريبي منا</h4>
      <p className="gd-sum">السعر الحالي حوالي {(s.close / mid * 100).toFixed(0)}% من القيمة الدفترية التقديرية، يعني السوق مسعّر الأصول بخصم، وممكن يكون لسبب (سيولة، تقييم العقارات).<small>تقدير دفتري، تقدير تجريبي منا.</small></p>
      <div className="gd-rng"><div><small>عقارات -10%</small><b dir="ltr">{lo}</b></div><div><small>بالقوائم</small><b dir="ltr">{mid}</b></div><div><small>عقارات +10%</small><b dir="ltr">{hi}</b></div></div>
      <Det>
      <p className="gd-lead">السعر الحالي <bdi dir="ltr">{f(s.close)}</bdi> يعني حوالي {(s.close / mid * 100).toFixed(0)}% من القيمة الدفترية. يعني السوق بيدفع في السهم أقل من المكتوب في دفاتر الشركة. ده مش معناه إن السعر هيرجع للدفترية: الخصم ممكن يكون له سبب، زي إن السهم صعب يتباع بسهولة (سيولة ضعيفة)، أو إن السوق مش مصدق تقييم العقارات، أو إن بيع العقارات ليه تكلفة.</p>
      <p className="gd-foot">القسمة على 1,874.84 مليون سهم. عدد الأسهم 1,874,843,549 حسب إفصاح 13 أكتوبر 2026 (موقف 30 سبتمبر، ومفيش أسهم خزينة في النموذج). شراء الخزينة: غير متوفر: ما لقيناش إفصاح رسمي بالرقم ده. نموذج 30 سبتمبر مفيهوش أسهم خزينة، ونصوص إفصاحات البورصة الخاصة بالشراء مش متاحة لنا. عدد الأسهم المستخدم هو اللي في النموذج، وأي شراء بعد 30 سبتمبر مش محسوب. القوائم منفردة (الشركة وحدها، مفيش قوائم مجمعة ولا حقوق أقلية).</p></Det></div>;
  }
  const m = FV[k];
  if (!m) return null;
  const eps = (m.profit / m.shares) * (4 / 3);
  const custom = !!m.mult; const mm: number[] = m.mult || [6.67, 10, 17.36]; const fx = (x: number) => (custom ? x : Math.round(x * 10) / 10) + '×';
  const mult: [string, number, string][] = [['محافظ', mm[0], fx(mm[0])], ['متوسط', mm[1], fx(mm[1])], ['متفائل', mm[2], fx(mm[2])]];
  const rows = mult.map(([n, x, t]) => ({ n, t, v: eps * x }));
  const pe = s.close / eps;
  const pos = s.close < rows[0].v ? 'أقل من' : s.close > rows[2].v ? 'أعلى من' : 'جوه';
  return <div className="gd-fv"><h4>نطاق السعر العادل التقديري · على قوائم {per(k).ttl || per(k).lab + ' 2026'}</h4>
    <p className="gd-sum">{m.nocmp ? <>النطاق ده بالدولار (محافظ {f(rows[0].v)}، متفائل {f(rows[2].v)} دولار). السعر على الصفحة دي بالجنيه، فمفيش مقارنة مباشرة بينهم.<small>تقدير على قوائم 9 شهور 2026 بالدولار، تقدير تجريبي منا.</small></> : <>{pos === 'أقل من' ? 'السعر الحالي تحت أقل رقم في النطاق التقديري' : pos === 'أعلى من' ? 'السعر الحالي فوق أعلى رقم في النطاق التقديري' : 'السعر الحالي جوه النطاق التقديري'} (المحافظ {f(rows[0].v)}، المتفائل {f(rows[2].v)}){pos === 'أقل من' ? '، يعني السوق مسعّر الأرباح بمضاعف أقل من الافتراضات. مش معناه إنه رخيص، ممكن السوق متوقع ربح أقل.' : pos === 'أعلى من' ? '، يعني السوق مسعّر الأرباح بمضاعف أعلى من الافتراضات.' : rows[2].v / rows[0].v > 2 ? '، وهو واسع (الفرق بين أقل وأعلى رقم أكتر من ضعفين)، فمش بيحدد حاجة لوحده.' : '.'}<small>تقدير على قوائم {per(k).ttl || per(k).lab + ' 2026'}، تقدير تجريبي منا.</small></>}</p>
    <div className="gd-rng">{rows.map(r => <div key={r.n}><small>{r.n} · {r.t}</small><b dir="ltr">{f(r.v)}</b></div>)}</div>
    <Det>
    <p className="gd-lead">{custom ? <>الربح المستخدم <bdi dir="ltr">{n1(m.profit)}</bdi> مليون ÷ <bdi dir="ltr">{n1(m.shares)}</bdi> مليون سهم. طريقة تحويله لسنة والمضاعفات المستخدمة مكتوبة في حدود الدراسة تحت</> : <>ربح السهم الحسابي <bdi dir="ltr">{eps.toFixed(eps < 0.1 ? 4 : 2)}</bdi> (ربح الأم 9 شهور <bdi dir="ltr">{n1(m.profit)}</bdi> مليون ÷ <bdi dir="ltr">{n1(m.shares)}</bdi> مليون سهم، مضروب في 4/3 عشان نقدّر سنة كاملة)</>}. {m.nocmp || custom ? '' : <>السعر الحالي <bdi dir="ltr">{f(s.close)}</bdi> يساوي {pe.toFixed(1)} مرة الربح، يعني بتدفع {pe.toFixed(1)} جنيه عشان تاخد جنيه ربح في السنة.</>}</p>
    {m.nocmp ? null : custom ? <p className="gd-lead">السعر الحالي {pos} النطاق التقديري. النطاق بيعرض تلات سيناريوهات بدل رقم واحد، لأن محدش عارف المضاعف الصح. المضاعفات المستخدمة {mm.join(' / ')} وأساسها مكتوب تحت في حدود الدراسة.</p> : <p className="gd-lead">السعر الحالي {pos} النطاق التقديري. النطاق واسع عن قصد: المحافظ بيفترض إنك عايز عائد أعلى من سعر الإيداع لليلة واحدة عند المركزي 20% (قرار 29 أكتوبر 2026)، فبيدفع أقل في كل جنيه ربح. المتوسط والمتفائل على مضاعف سوق البورصة، وده أعلى. محدش عارف الرقم الصح، عشان كده الأرقام التلاتة.</p>}
    {!m.nocmp && <div className="gd-it ok"><div className="gd-h"><span>القراءة الحالية</span></div><p>الوسط ({rows[1].t}) = <bdi dir="ltr">{f(rows[1].v)}</bdi>، وده السعر لو السهم اتسعّر بـ{custom ? mm[1] + ' مرة' : 'عشر أمثال'} ربحه السنوي. السعر الحالي {s.close > rows[1].v ? 'فوق' : 'تحت'} الوسط بحوالي {Math.abs((s.close / rows[1].v - 1) * 100).toFixed(0)}%، و{s.close > rows[0].v ? 'فوق' : 'تحت'} الحد المحافظ بحوالي {Math.abs((s.close / rows[0].v - 1) * 100).toFixed(0)}%. {custom ? '' : 'الحد المحافظ مبني على الافتراض ده، ومش بالضرورة الأقرب للواقع. سعر المركزي للبنوك مش عائد الودائع للأفراد.'} دي قراءة بالأرباح، مش توقع سعر، وأي رقم من القايمة تحت لو اتغير بيحرك النطاق.</p></div>}
    {custom ? <div className="gd-it mid"><div className="gd-h"><span>الطريقة</span></div><p>الفكرة: السعر = ربح السهم في السنة × مضاعف ربح. المضاعفات المستخدمة لهذا السهم {mm.join(' / ')}، وافتراضاتها في حدود الدراسة تحت.</p></div> : <div className="gd-it mid"><div className="gd-h"><span>الطريقة</span></div><p>الفكرة: السعر = ربح السهم في السنة × رقم بيعبّر عن "كام سنة ربح مستعد أدفع تمنها" (اسمه مضاعف الربح). المحافظ = 1 ÷ (سعر الإيداع لليلة واحدة عند المركزي 20% (قرار 29 أكتوبر 2026) + علاوة مخاطرة 7% − نمو بحجم التضخم 12%) = 6.67، يعني رقم صغير لما العائد المرجعي يبقى عالي. المتوسط والمتفائل = مضاعف سوق البورصة المصرية: 10 في أغسطس و17.4 في أكتوبر.</p></div>}
    {custom ? null : <div className="gd-it mid"><div className="gd-h"><span>الافتراضات (علاوة المخاطرة 7% افتراضنا)</span></div><p>ضرب ربح 9 شهور في 4/3 بيفترض إن الربع الرابع زي متوسط الـ9 شهور، وده مش مضمون. علاوة المخاطرة 7% افتراضنا إحنا مش رقم رسمي. والمضاعف المناسب بيختلف من قطاع لقطاع، فالنطاق ده تقدير تجريبي منا.</p></div>}
    <div className="gd-it no"><div className="gd-h"><span>حدود الدراسة: مش متاح من مصادر مجانية، هيتحدث لما يتنشر</span></div>{m.todo.map((t: string, i: number) => <p key={i}>• {t}</p>)}</div>
    {m.extra && <div className="gd-it mid"><div className="gd-h"><span>تقاطع آخر</span></div><p>{m.extra}</p></div>}
    <p className="gd-foot">مصادر: <a href="https://sis.gov.eg/en/media-center/news/egypt-s-central-bank-raises-key-interest-rates-by-1/" target="_blank" rel="noreferrer">سعر الإيداع لليلة عند المركزي 20% (29 أكتوبر 2026)</a> · <a href="https://economymiddleeast.com/news/egypts-october-inflation-eases-to-12-percent-as-monthly-rate-falls-to-0-6-percent-after-march-peak/" target="_blank" rel="noreferrer">تضخم أكتوبر 12%</a> · <a href="https://enterpriseam.com/egypt/2026/11/05/egx30-sheds-4-43-in-october-to-post-its-first-back-to-back-monthly-loss-of-2026/" target="_blank" rel="noreferrer">مضاعف السوق 17.36</a> · <a href="https://www.agbi.com/analysis/markets/2026/08/foreign-investors-return-as-egypt-stocks-hit-record-highs/" target="_blank" rel="noreferrer">مضاعف 10 في أغسطس</a> · {m.src}.</p>    </Det></div>;
}


